{"path":"src/java_module.java","content":"// Метод ищет активного пользователя по логину.
// Возвращаем Optional, чтобы явно показать: пользователь может отсутствовать,
// а вызывающий код обязан обработать этот случай (например, через isPresent/getOrElse).
public Optional<User> findActive(String login) {
    // Берём поток из коллекции всех пользователей.
    return users.stream()
        // Первый фильтр: совпадение логина без учёта регистра.
        // Используем equalsIgnoreCase, потому что пользователи часто вводят
        // логин с разным регистром, а для нас это один и тот же аккаунт.
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Второй фильтр: пользователь должен быть активным.
        // Активность определяется двумя условиями:
        // 1) пользователь не заблокирован (!u.isBlocked());
        // 2) срок действия учётной записи ещё не истёк —
        //    дата истечения строго позже текущего момента времени.
        // Объединяем условия через &&, чтобы требовалось выполнение обоих сразу.
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Берём первый найденный подходящий элемент.
        // findFirst возвращает Optional.empty(), если подходящего нет,
        // поэтому метод корректно обрабатывает отсутствие результата.
        .findFirst();
}
"}

{"path":"src/csharp_module.cs","content":"/// <summary>
/// Универсальный механизм повторных попыток (retry) для асинхронных операций.
/// </summary>
/// <param name="action">Асинхронная операция, возвращающая int (например, HTTP-статус или код ответа).</param>
/// <param name="attempts">Максимальное количество попыток выполнения операции.</param>
/// <returns>Результат успешно выполненной операции.</returns>
/// <exception cref="InvalidOperationException">Брошена только теоретически недостижимая ошибка — на практике метод либо вернёт результат, либо пробросит исключение из последней попытки.</exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Перебираем попытки с 0 до attempts-1.
    // Индекс i используется и как счётчик попыток, и как степень для экспоненциальной задержки.
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Выполняем операцию. Если она завершилась успешно — сразу возвращаем результат,
            // не тратя оставшиеся попытки.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Повторяем попытку ТОЛЬКО при сетевых/HTTP-ошибках (HttpRequestException).
            // Другие исключения (логические ошибки, баги) пробрасываем наружу без повторов —
            // это осознанный выбор: ретраить нет смысла, если проблема не в сети.
            //
            // Условие "when (i < attempts - 1)" гарантирует, что после последней неудачной
            // попытки мы НЕ засыпаем зря, а просто выходим из цикла и даём исходному
            // исключению распространиться дальше (см. комментарий ниже про throw).
            //
            // Экспоненциальная задержка: 200мс * 2^i => 200мс, 400мс, 800мс, 1600мс...
            // Такой подход ("exponential backoff") снижает нагрузку на перегруженный сервер
            // и даёт ему время восстановиться между запросами.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // На практике эта строка недостижима:
    //  - успешный вызов action() завершает метод через return;
    //  - HttpRequestException на последней попытке не перехватывается (условие when ложно),
    //    поэтому пробрасывается наружу;
    //  - любое другое исключение тоже пробрасывается.
    // Но компилятор C# требует, чтобы метод гарантированно завершался,
    // поэтому оставляем явный throw с понятным сообщением.
    throw new InvalidOperationException("unreachable");
}
"}

{"path":"src/go_module.go","content":"// Функция worker — «рабочая» горутина в пуле.
// Она читает задачи из канала jobs, обрабатывает каждую и отправляет
// результат в канал results.
//
// Почему именно так:
//   - Каналы (jobs/results) — это основной механизм обмена данными между
//     горутинами в Go. Они обеспечивают безопасную передачу без гонок данных
//     (data race), поэтому нам не нужны явные блокировки (mutex).
//   - sync.WaitGroup позволяет координирующей стороне дождаться завершения
//     всех воркеров перед выходом из программы.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // defer wg.Done() гарантирует, что счётчик WaitGroup будет уменьшён
    // при любом выходе из функции (в том числе при панике или ошибке).
    // Это важнее, чем вызывать wg.Done() вручную в конце, потому что
    // мы не забудем об этом при добавлении новых путей выхода.
    defer wg.Done()

    // for j := range jobs — цикл, который автоматически завершится,
    // когда канал jobs будет закрыт (close). Это стандартный идиоматичный
    // способ «потребления» задач из канала в Go.
    for j := range jobs {
        // process(j) выполняет фактическую работу над задачей.
        // Возвращает результат r и возможную ошибку err.
        r, err := process(j)

        if err != nil {
            // При ошибке логируем её вместе с идентификатором задачи,
            // чтобы можно было отследить, какая именно задача упала.
            // Используем continue, а не return, чтобы одна неудачная
            // задача не убивала весь воркер — остальные задачи всё равно
            // должны быть обработаны.
            log.Printf("job %d: %v", j.ID, err)
            continue
        }

        // Отправляем успешный результат в канал results.
        // Операция блокируется, пока потребитель не заберёт значение —
        // это естественное ограничение скорости (backpressure):
        // воркер не будет работать быстрее, чем потребляется результат.
        results <- r
    }
}
"}

{"path":"src/rust_module.rs","content":"use std::collections::HashMap;

/// Разбирает строку в формате "ключ1=значение1;ключ2=значение2" в словарь.
///
/// Формат входной строки: пары «ключ=значение», разделённые точкой с запятой.
/// Пример: `"Name=Alice; Age=30"` -> { "name": "Alice", "age": "30" }.
///
/// Почему именно так:
/// - Используем ленивый итератор (split/filter_map/map/collect), чтобы не создавать
///   промежуточные коллекции — это экономит память и время на больших строках.
/// - `filter_map` с `split_once('=')` отбрасывает части, где нет знака '=',
///   то есть повреждённые/пустые сегменты просто игнорируются, а не вызывают панику.
/// - Ключ нормализуем: убираем пробелы по краям (`trim`) и приводим к нижнему
///   регистру (`to_lowercase`), чтобы "Name" и "name" считались одним ключом.
/// - Значение тоже очищаем от лишних пробелов, но сохраняем его регистр как есть.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';') // разбиваем строку на сегменты по ';'
        .filter_map(|p| p.split_once('=')) // берём только сегменты, содержащие '=';
                                           // split_once возвращает Option<&(k, v)>
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string())) // нормализуем пару
        .collect() // собираем результат в HashMap
}
"}
